CREATE TABLE public.clube_hs_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), preapproval_id text UNIQUE NOT NULL, external_reference text, status text NOT NULL DEFAULT 'pending', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.clube_hs_subscriptions TO authenticated;
GRANT ALL ON public.clube_hs_subscriptions TO service_role;
ALTER TABLE public.clube_hs_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY club_subscription_own_read ON public.clube_hs_subscriptions FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.clube_hs_pix_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), amount numeric(12,2) NOT NULL DEFAULT 19.90 CHECK(amount=19.90), provider_payment_id text UNIQUE, preference_id text, checkout_url text, status text NOT NULL DEFAULT 'pending', paid_at timestamptz, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.clube_hs_pix_payments TO authenticated;
GRANT ALL ON public.clube_hs_pix_payments TO service_role;
ALTER TABLE public.clube_hs_pix_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY club_pix_own_read ON public.clube_hs_pix_payments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.club_has_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.clube_hs_subscriptions WHERE user_id=_user_id AND status='authorized') OR EXISTS(SELECT 1 FROM public.clube_hs_pix_payments WHERE user_id=_user_id AND status='approved' AND expires_at>now()) OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND p.is_clube_hs AND NOT EXISTS(SELECT 1 FROM public.clube_hs_pix_payments WHERE user_id=_user_id AND status='approved') AND NOT EXISTS(SELECT 1 FROM public.clube_hs_subscriptions WHERE user_id=_user_id)); $$;
REVOKE ALL ON FUNCTION public.club_has_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.club_has_access(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.protect_club_membership() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' OR auth.role()='anon' THEN IF (TG_OP='INSERT' AND NEW.is_clube_hs) OR (TG_OP='UPDATE' AND NEW.is_clube_hs IS DISTINCT FROM OLD.is_clube_hs) THEN RAISE EXCEPTION 'A assinatura só pode ser atualizada após confirmação segura do pagamento.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_club_membership BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_club_membership();
CREATE OR REPLACE FUNCTION public.apply_club_pix_payment(_id uuid,_payment_id text,_status text,_amount numeric,_currency text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.clube_hs_pix_payments%ROWTYPE; BEGIN SELECT * INTO p FROM public.clube_hs_pix_payments WHERE id=_id FOR UPDATE; IF NOT FOUND OR _amount<>p.amount OR _currency<>'BRL' OR (p.provider_payment_id IS NOT NULL AND p.provider_payment_id<>_payment_id) THEN RAISE EXCEPTION 'Pagamento do Clube não corresponde à cobrança.'; END IF; IF p.status='approved' THEN RETURN; END IF; UPDATE public.clube_hs_pix_payments SET provider_payment_id=_payment_id,status=_status,paid_at=CASE WHEN _status='approved' THEN now() END,expires_at=CASE WHEN _status='approved' THEN greatest(now(),coalesce((SELECT max(expires_at) FROM public.clube_hs_pix_payments WHERE user_id=p.user_id AND status='approved'),now()))+interval '1 month' END WHERE id=p.id; IF _status='approved' THEN UPDATE public.profiles SET is_clube_hs=true WHERE id=p.user_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.apply_club_pix_payment(uuid,text,text,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_club_pix_payment(uuid,text,text,numeric,text) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_social_media() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='audio' AND NOT public.club_has_access(NEW.sender_id) THEN RAISE EXCEPTION 'Envio de áudio exclusivo para assinantes do Clube HS.'; END IF; IF NEW.kind IN('image','audio') AND (NEW.media_path IS NULL OR split_part(NEW.media_path,'/',1)<>NEW.sender_id::text OR NEW.media_path LIKE '%..%') THEN RAISE EXCEPTION 'Mídia não pertence ao remetente.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_social_media BEFORE INSERT OR UPDATE ON public.social_messages FOR EACH ROW EXECUTE FUNCTION public.guard_social_media();
CREATE TRIGGER guard_social_group_media BEFORE INSERT OR UPDATE ON public.social_group_messages FOR EACH ROW EXECUTE FUNCTION public.guard_social_media();
CREATE TABLE public.account_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),kind text NOT NULL CHECK(kind IN('social','sale','purchase')),title text NOT NULL,body text NOT NULL,target_id uuid NOT NULL,event_key text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
GRANT SELECT,DELETE ON public.account_notifications TO authenticated;
GRANT UPDATE(read_at) ON public.account_notifications TO authenticated;
GRANT ALL ON public.account_notifications TO service_role;
ALTER TABLE public.account_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_read_own ON public.account_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notification_update_own ON public.account_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY notification_delete_own ON public.account_notifications FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE INDEX notification_unread ON public.account_notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE OR REPLACE FUNCTION public.notify_social_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; sender text; BEGIN SELECT coalesce(full_name,'Contato HS') INTO sender FROM public.profiles WHERE id=NEW.sender_id; SELECT CASE WHEN member_a=NEW.sender_id THEN member_b ELSE member_a END INTO recipient FROM public.social_conversations WHERE id=NEW.conversation_id; INSERT INTO public.account_notifications(user_id,kind,title,body,target_id,event_key) VALUES(recipient,'social','Nova mensagem na HS Social',sender||CASE WHEN NEW.kind='audio' THEN ' enviou um áudio' WHEN NEW.kind='image' THEN ' enviou uma foto' ELSE ' enviou uma mensagem' END,NEW.conversation_id,'social:'||NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER notify_social_message AFTER INSERT ON public.social_messages FOR EACH ROW EXECUTE FUNCTION public.notify_social_message();
CREATE OR REPLACE FUNCTION public.notify_social_group_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.account_notifications(user_id,kind,title,body,target_id,event_key) SELECT m.user_id,'social','Nova mensagem no grupo',g.name,NEW.group_id,'group:'||NEW.id FROM public.social_group_members m JOIN public.social_groups g ON g.id=m.group_id WHERE m.group_id=NEW.group_id AND m.user_id<>NEW.sender_id ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER notify_social_group_message AFTER INSERT ON public.social_group_messages FOR EACH ROW EXECUTE FUNCTION public.notify_social_group_message();
CREATE OR REPLACE FUNCTION public.notify_approved_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='approved' AND OLD.status IS DISTINCT FROM 'approved' THEN INSERT INTO public.account_notifications(user_id,kind,title,body,target_id,event_key) SELECT owner_id,'sale','Venda aprovada','Pagamento confirmado · Pedido '||upper(left(NEW.order_id::text,8)),NEW.order_id,'sale:'||NEW.id FROM public.stores WHERE id=NEW.store_id ON CONFLICT DO NOTHING; INSERT INTO public.account_notifications(user_id,kind,title,body,target_id,event_key) VALUES(NEW.buyer_id,'purchase','Pagamento confirmado','Sua compra foi aprovada · Pedido '||upper(left(NEW.order_id::text,8)),NEW.order_id,'purchase:'||NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_approved_sale AFTER UPDATE OF status ON public.payment_transactions FOR EACH ROW EXECUTE FUNCTION public.notify_approved_sale();
ALTER PUBLICATION supabase_realtime ADD TABLE public.account_notifications;
CREATE TABLE public.trend_pinned_comments(video_id uuid PRIMARY KEY REFERENCES public.trend_videos(id) ON DELETE CASCADE,comment_id uuid NOT NULL UNIQUE REFERENCES public.trend_comments(id) ON DELETE CASCADE,pinned_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trend_pinned_comments TO authenticated;
GRANT ALL ON public.trend_pinned_comments TO service_role;
ALTER TABLE public.trend_pinned_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY trend_pins_read ON public.trend_pinned_comments FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.trend_pin_comment(_video_id uuid,_comment_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN SELECT user_id INTO owner FROM public.trend_videos WHERE id=_video_id FOR UPDATE; IF auth.uid() IS NULL OR (owner IS DISTINCT FROM auth.uid() AND NOT public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Somente o autor do post pode fixar comentários.'; END IF; IF _comment_id IS NULL THEN DELETE FROM public.trend_pinned_comments WHERE video_id=_video_id; ELSE IF NOT EXISTS(SELECT 1 FROM public.trend_comments WHERE id=_comment_id AND video_id=_video_id AND parent_id IS NULL) THEN RAISE EXCEPTION 'Comentário inválido para este post.'; END IF; INSERT INTO public.trend_pinned_comments(video_id,comment_id) VALUES(_video_id,_comment_id) ON CONFLICT(video_id) DO UPDATE SET comment_id=EXCLUDED.comment_id,pinned_at=now(); END IF; END $$;
REVOKE ALL ON FUNCTION public.trend_pin_comment(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.trend_pin_comment(uuid,uuid) TO authenticated;
